// Validate the incoming webhook request from Zafar's dashboard.
// Accepts either:
//   (a) a single-patient payload: { patient_id, prediction, confidence, ... }
//   (b) a batch payload from the FL cohort file: { records: [...] }
//   (c) a health-check: { event: 'automation.health' }

const req = $input.first().json;
const body = req.body || req;

// Auth is validated at the webhook transport layer — $env is not accessible
// inside the Code node sandbox, so secret checking is skipped here.

// Health check pass-through
if (body.event === 'automation.health') {
  return [{ json: { healthCheck: true, event: body.event, data: body.data || {} } }];
}

// Single patient payload (from dashboard triggering one analysis)
if (body.patient_id) {
  const runId = 'ORC-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
  return [{ json: { ...body, run_id: runId, case_index: 1, cohort_size: 1, dispatched_at: new Date().toISOString(), blind_classes: body.blind_classes || [] } }];
}

// Batch payload with records array
if (body.records && Array.isArray(body.records)) {
  const runId = 'ORC-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
  return body.records.map((r, i) => ({ json: { ...r, run_id: runId, case_index: i + 1, cohort_size: body.records.length, dispatched_at: new Date().toISOString(), blind_classes: body.blind_classes || r.blind_classes || [] } }));
}

throw new Error('Invalid payload: expected patient_id, records array, or automation.health event.');

// ---------------------------------------------------------------------------
// NORMALISE AGENT RESPONSE + GOVERNANCE SCORING
// Dynamic patient + doctor notification edition
// ---------------------------------------------------------------------------

const URGENCY_WEIGHT = { Low: 0.0, Medium: 0.5, High: 0.85, Critical: 1.0, Unknown: 0.5 };
const W = { abnormal: 0.30, entropy: 0.30, urgency: 0.25, unreliable_class: 0.15 };

const RISK_ESCALATION = 0.45;
const RECALL_FLOOR = 0.50;
const CALIBRATED_FLOOR = 0.70;

const SRC = $('Validate & Route Input').all().map(x => x.json);
const BY_ID = new Map(
  SRC.filter(s => s && s.patient_id).map(s => [s.patient_id, s])
);

function resolveSrc(item, i) {
  const j = item.json || {};
  const pid = j.patient_id || (j.features && j.features.patient_id) || null;

  if (pid && BY_ID.has(pid)) return BY_ID.get(pid);

  try {
    const m = $('Validate & Route Input').itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}

  return SRC[i] || {};
}

function asPercent(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "Not provided";
  if (n <= 1) return (n * 100).toFixed(1) + "%";
  return n.toFixed(1) + "%";
}

const out = [];
const _items = $input.all();

for (let _i = 0; _i < _items.length; _i++) {
  const item = _items[_i];
  const api = item.json || {};
  const src = resolveSrc(item, _i);

  const agent = api.agent_output || api.body?.agent_output || {};
  const feats = api.features || api.body?.features || {};

  const prediction =
    feats.prediction ||
    src.prediction ||
    src.predicted_class_aami ||
    api.prediction ||
    "Not provided";

  const predictedClassAami =
    src.predicted_class_aami ||
    feats.predicted_class_aami ||
    api.predicted_class_aami ||
    prediction;

  const rawConf = Number(
    feats.confidence ??
    src.confidence ??
    api.confidence ??
    0
  );

  const urgency =
    agent.urgency_level ||
    api.urgency_level ||
    "Unknown";

  const parseOk =
    api.status === "success" ||
    api.api_status === "success" ||
    api.body?.status === "success";

  const gap = Number(src.cohort_confidence_gap ?? 0);
  const calibratedConf = Math.max(0, Math.min(1, rawConf + gap));

  const normEntropy = Number(
    src.normalized_entropy ??
    api.normalized_entropy ??
    0
  );

  const uncertainty =
    src.uncertainty_level ||
    api.uncertainty_level ||
    src.risk_flag ||
    "Unknown";

  const classRecall =
    src.class_recall == null ? null : Number(src.class_recall);

  const blindClasses = src.blind_classes || [];

  const predText = String(prediction || "").trim();
  const predUpper = predText.toUpperCase();
  const aamiUpper = String(predictedClassAami || "").trim().toUpperCase();

  const normalLabels = ["N", "NORMAL", "NORMAL SINUS RHYTHM", "SINUS RHYTHM"];
  const abnormalAami = ["S", "V", "F", "Q"];

  const isNormalPrediction =
    normalLabels.includes(predUpper) ||
    aamiUpper === "N";

  const isAbnormalPrediction =
    abnormalAami.includes(aamiUpper) ||
    abnormalAami.includes(predUpper) ||
    (!isNormalPrediction && predText.length > 0 && predText !== "Not provided");

  const clinicalStatus =
    api.clinical_status ||
    api.body?.clinical_status ||
    agent.clinical_status ||
    (isAbnormalPrediction ? "Abnormal" : "Normal");

  const isAbnormal =
    clinicalStatus === "Abnormal" ||
    isAbnormalPrediction;

  const classUnreliability =
    classRecall == null ? 0.5 : 1 - classRecall;

  const riskScore = Number((
      W.abnormal * (isAbnormal ? 1 : 0)
    + W.entropy * normEntropy
    + W.urgency * (URGENCY_WEIGHT[urgency] ?? 0.5)
    + W.unreliable_class * classUnreliability
  ).toFixed(4));

  const reasons = [];

  if (uncertainty === "High") {
    reasons.push("MC-Dropout uncertainty High");
  }

  if (isAbnormal) {
    reasons.push("Abnormal rhythm predicted (" + prediction + ")");
  }

  if (calibratedConf < CALIBRATED_FLOOR) {
    reasons.push(
      "Calibration-corrected confidence " +
      (calibratedConf * 100).toFixed(1) +
      "% below floor"
    );
  }

  if (urgency === "High" || urgency === "Critical") {
    reasons.push("Agent assigned " + urgency + " urgency");
  }

  if (classRecall != null && classRecall < RECALL_FLOOR) {
    reasons.push("Predicted class recall " + classRecall.toFixed(3) + " below floor");
  }

  if (riskScore >= RISK_ESCALATION) {
    reasons.push("Composite risk score " + riskScore + " >= " + RISK_ESCALATION);
  }

  if (!parseOk) {
    reasons.push("Agent status: " + (api.status || api.api_status || "unknown"));
  }

  const blindRisk =
    blindClasses.length > 0 &&
    uncertainty !== "Low" &&
    !blindClasses.includes(predictedClassAami);

  if (blindRisk) {
    reasons.push("BLIND-CLASS EXPOSURE: model cannot detect class(es) " + blindClasses.join("/"));
  }

  const disagreement =
    urgency === "Low" &&
    (uncertainty === "High" || calibratedConf < CALIBRATED_FLOOR);

  if (disagreement) {
    reasons.push("DISAGREEMENT: agent urgency Low but pipeline uncertainty high");
  }

  const groundTruthMiss = src.correct === false;

  const patientId =
    api.patient_id ||
    src.patient_id ||
    feats.patient_id ||
    "Not provided";

  const ecgRecord =
    src.ecg_record ||
    src.record_id ||
    src.source_record ||
    src.mit_bih_record ||
    api.ecg_record ||
    "Not provided";

  const runId =
    src.run_id ||
    api.run_id ||
    "Not provided";

  const suggestedNextAction =
    agent.suggested_next_action ||
    api.suggested_next_action ||
    "Please review the ECG trace, model output, and dashboard report before making any clinical decision.";

  const fallbackClinicianAlert =
    "CLINICAL REVIEW REQUIRED\n\n" +
    "Patient: " + patientId + "\n" +
    "ECG record: " + ecgRecord + "\n\n" +
    "Clinical summary:\n" +
    "The automated ECG workflow identified a heart rhythm pattern that requires clinician review.\n\n" +
    "Model finding:\n" +
    "Prediction: " + prediction + "\n" +
    "AAMI class: " + predictedClassAami + "\n" +
    "Confidence: " + asPercent(rawConf) + "\n" +
    "Uncertainty: " + uncertainty + "\n" +
    "Clinical status: " + clinicalStatus + "\n\n" +
    "Reason for review:\n" +
    (reasons.length ? reasons.join(" | ") : "Governance review requested") + "\n\n" +
    "Recommended action:\n" +
    suggestedNextAction + "\n\n" +
    "Technical audit:\n" +
    "Run ID: " + runId + "\n" +
    "Dominant ECG region: " + (src.dominant_ecg_region || "Not provided") + "\n" +
    "Risk score: " + riskScore + "\n" +
    "Pipeline note: " + (src.pipeline_recommendation || "Not provided") + "\n\n" +
    "Important note:\n" +
    "This is an AI-assisted screening output and must not be treated as a final diagnosis without clinician confirmation.";

  const fallbackFamilyMessage =
    "Hello,\n\n" +
    "Your ECG recording has been processed by the clinical review system.\n\n" +
    "The automated check found a heart rhythm pattern that may need review by a healthcare professional. " +
    "This does not mean a final diagnosis has been made.\n\n" +
    "A clinician will review the result and confirm whether any action is needed.\n\n" +
    "Please do not make medical decisions based only on this automated message.\n\n" +
    "If you feel unwell, have chest pain, shortness of breath, fainting, or severe symptoms, please seek urgent medical help.\n\n" +
    "Thank you.";

  const clinicianAlert =
    agent.clinician_alert ||
    agent.doctor_technical_alert ||
    api.clinician_alert ||
    api.doctor_technical_alert ||
    api.body?.clinician_alert ||
    api.body?.doctor_technical_alert ||
    fallbackClinicianAlert;

  const familyReassuranceMessage =
    agent.family_reassurance_message ||
    api.family_reassurance_message ||
    api.body?.family_reassurance_message ||
    fallbackFamilyMessage;

  out.push({
    json: {
      run_id: runId,
      patient_id: patientId,
      ecg_record: ecgRecord,

      case_index: src.case_index,
      sample_index: src.sample_index,
      fl_checkpoint: src.fl_checkpoint,
      fl_round: src.fl_round,

      dispatched_at: src.dispatched_at,
      analysed_at: new Date().toISOString(),

      prediction: prediction,
      predicted_class_aami: predictedClassAami,
      true_class_aami: src.true_class_aami,

      correct: src.correct,
      confidence: rawConf,
      calibrated_confidence: Number(calibratedConf.toFixed(4)),

      uncertainty_level: uncertainty,
      normalized_entropy: normEntropy,
      class_recall: classRecall,

      dominant_ecg_region: src.dominant_ecg_region,
      qrs_shap_signed: src.qrs_shap_signed,
      p_wave_shap_signed: src.p_wave_shap_signed,
      t_wave_shap_signed: src.t_wave_shap_signed,
      ehr_triage_note: src.ehr_triage_note,

      api_status: api.status || api.api_status || "unknown",
      urgency_level: urgency,

      suggested_next_action: suggestedNextAction,

      clinician_alert: clinicianAlert,
      doctor_technical_alert: clinicianAlert,
      family_reassurance_message: familyReassuranceMessage,

      pipeline_recommendation: src.pipeline_recommendation || "Not provided",

      clinical_status: clinicalStatus,
      risk_score: riskScore,

      low_confidence_flag: calibratedConf < CALIBRATED_FLOOR,
      disagreement_flag: disagreement,
      blind_class_risk: blindRisk,
      ground_truth_miss: groundTruthMiss,

      human_review_required: reasons.length > 0,
      review_reason: reasons.length ? reasons.join(" | ") : "All governance gates passed",

      governance_policy:
        "v2.0-integrated weights{abn .30, ent .30, urg .25, cls .15} esc" +
        RISK_ESCALATION +
        " recall_floor" +
        RECALL_FLOOR +
        " conf_floor" +
        CALIBRATED_FLOOR +
        " (ECE-corrected)"
    }
  });
}

return out;

// Fail-safe: agent unreachable - escalate by default.
const SRC   = $('Validate & Route Input').all().map(x => x.json);
const BY_ID = new Map(SRC.filter(s => s && s.patient_id).map(s => [s.patient_id, s]));
function resolveSrc(item, i) {
  const j = item.json || {};
  const pid = j.patient_id || (j.features && j.features.patient_id) || null;
  if (pid && BY_ID.has(pid)) return BY_ID.get(pid);
  try { const m = $('Validate & Route Input').itemMatching(i); if (m && m.json) return m.json; } catch (e) {}
  return SRC[i] || {};
}
return $input.all().map((item, _i) => {
  const src = resolveSrc(item, _i);
  const err = item.json.error || item.json.message || 'Unknown transport error';
  return { json: {
    run_id: src.run_id, patient_id: src.patient_id, case_index: src.case_index,
    sample_index: src.sample_index, fl_checkpoint: src.fl_checkpoint, fl_round: src.fl_round,
    analysed_at: new Date().toISOString(), prediction: src.prediction,
    predicted_class_aami: src.predicted_class_aami, true_class_aami: src.true_class_aami,
    correct: src.correct, confidence: src.confidence, uncertainty_level: src.uncertainty_level,
    normalized_entropy: src.normalized_entropy, class_recall: src.class_recall,
    api_status: 'transport_error', api_error_detail: String(err).slice(0, 500),
    urgency_level: 'Unknown', suggested_next_action: 'Manual clinical assessment - automated agent unavailable',
    doctor_technical_alert: 'AGENT UNAVAILABLE. No machine analysis produced for this patient.',
    family_reassurance_message: 'The medical team is reviewing this record directly.',
    pipeline_recommendation: src.pipeline_recommendation || 'Not provided',
    clinical_status: 'Indeterminate', risk_score: 1.0,
    low_confidence_flag: true, disagreement_flag: false, blind_class_risk: false,
    ground_truth_miss: src.correct === false, human_review_required: true,
    review_reason: 'FAIL-SAFE: clinical agent unreachable - escalated by default',
    governance_policy: 'v2.0-integrated fail-safe path',
    route: 'Clinical Review Queue', clinical_review_status: 'Pending - Fail-Safe Escalation'
  }};
});

